sev_order = {"fatal": 0, "major": 1, "minor": 2}
for i in issues:
    assert set(i) == {"id", "file", "label_or_line", "severity", "problem", "evidence", "fix"}, i["id"]
    assert i["severity"] in sev_order
ids = [i["id"] for i in issues]
assert len(ids) == len(set(ids))

out_json = os.path.join(HERE, "..", "issues-readability.json")
with open(out_json, "w", encoding="utf-8") as f:
    json.dump(issues, f, ensure_ascii=False, indent=1)

lines = []
for i in issues:
    lines.append(f"{i['id'][2:].lstrip('0')}. **{i['id']} [{i['severity']}]** `{i['file']}`, {i['label_or_line']}.  ")
    lines.append(f"   *Problem.* {i['problem']}  ")
    lines.append(f"   *Evidence.* {i['evidence']}  ")
    lines.append(f"   *Fix.* {i['fix']}")
    lines.append("")
with open(os.path.join(HERE, "r_issue_list.md"), "w", encoding="utf-8") as f:
    f.write("\n".join(lines))
from collections import Counter
print(len(issues), Counter(i["severity"] for i in issues))
